<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {useI18n} from 'vue-i18n';
import {apiUrl} from '../lib/urls';
const {locale}=useI18n();const zh=computed(()=>locale.value==='zh-CN');const label=(a:string,b:string)=>zh.value?a:b;
import {forumUser as user,forumToken as token} from '../stores/community';
interface Post{id:number;parent:number|null;title:string;body:string;author:string;created:string;status:string;own:number;reports?:number}
const posts=ref<Post[]>([]),queue=ref<Post[]>([]),topic=ref<Post|null>(null),busy=ref(false),message=ref('');
const mode=ref('login'),name=ref(''),password=ref(''),accept=ref(false),title=ref(''),body=ref(''),reportId=ref(0),reason=ref(''),confirmName=ref('');
async function api(path:string,data?:unknown){const response=await fetch(apiUrl('/api/v1/community/'+path),{method:data?'POST':'GET',credentials:'omit',headers:{Accept:'application/json',...(data?{'Content-Type':'application/json'}:{}),...(token.value?{Authorization:'Bearer '+token.value}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});const value=await response.json();if(response.status===401){user.value=null;token.value='';}if(!response.ok)throw Error(value.error||'Service unavailable');return value;}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action();}catch(error){message.value=error instanceof Error?error.message:'Service unavailable';}finally{busy.value=false;}}
async function load(){posts.value=(await api('posts'+(topic.value?'?parent='+topic.value.id:''))).items;if(user.value?.admin)queue.value=(await api('moderation')).items;}
function login(){void run(async()=>{const value=await api(mode.value,{name:name.value,password:password.value,accept:accept.value});token.value=value.token;user.value=value.user;password.value='';await load();});}
function publish(){void run(async()=>{await api('posts',{title:topic.value?'回复 / Reply: '+topic.value.title:title.value,body:body.value,parent:topic.value?.id});title.value='';body.value='';message.value=label('已提交，审核通过后公开。','Submitted. Visible publicly after moderation.');await load();});}
function select(value:Post|null){topic.value=value;void run(load);}
function moderate(id:number,status:string){void run(async()=>{await api('moderate',{id,status});await load();});}
function remove(id:number){void run(async()=>{await api('delete',{id});await load();});}
function logout(){void run(async()=>{await api('logout',{});user.value=null;token.value='';topic.value=null;await load();});}
function report(){void run(async()=>{await api('report',{id:reportId.value,reason:reason.value});reportId.value=0;reason.value='';message.value=label('举报已提交，内容暂停公开，等待管理员复核。','Reported. Content hidden pending review.');topic.value=null;await load();});}
function deleteAccount(){void run(async()=>{await api('delete-account',{confirm:confirmName.value});user.value=null;token.value='';confirmName.value='';topic.value=null;await load();});}
onMounted(()=>{void run(load);});
</script>
<template><div class="page-heading"><div><p class="eyebrow">NOBI / PADDOCK</p><h1 tabindex="-1">{{label('车迷论坛','Fan forum')}}</h1><p>{{label('分享比赛观点，尊重每一位车迷。','Race conversations, with respect for every fan.')}}</p></div></div>
<details class="world-preferences forum-policy"><summary>{{label('社区规则与账号隐私','Community rules & account privacy')}}</summary><p>{{label('仅讨论赛车；禁止辱骂歧视、违法信息、广告、泄露隐私及未经许可的文章或图片。帖子和回复经人工审核后公开，举报内容暂停展示。用户名公开，密码以加盐哈希保存；登录凭证仅在当前页面内存保存，刷新后需重新登录。无需邮箱，暂不支持自助找回密码。注销会删除账号、帖子和回复；数据库备份如存在，由运营者依留存政策处理。','Racing discussion only. No abuse, discrimination, illegal content, ads, private information or unlicensed articles/images. Posts and replies require moderation; reported content is hidden. Usernames are public; passwords are salted hashes. Sessions stay in page memory and require sign-in after reload. No email or self-service password recovery. Account deletion removes your account, posts and replies; any operator backups follow their retention policy.')}}</p><RouterLink to="/legal">{{label('隐私与来源说明','Privacy & sources')}} ↗</RouterLink></details>
<p v-if="message" role="status" class="notice">{{message}}</p>
<section v-if="!user" class="world-preferences"><h2>{{label('加入围场','Join the paddock')}}</h2><div class="filter-group"><button :aria-pressed="mode==='login'" @click="mode='login'">{{label('登录','Sign in')}}</button><button :aria-pressed="mode==='register'" @click="mode='register'">{{label('注册','Register')}}</button></div><form class="forum-form" @submit.prevent="login"><label>{{label('用户名（3–24 位字母、数字、下划线）','Username (3–24 letters, digits, underscores)')}}<input v-model="name" autocomplete="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" required/></label><label>{{label('密码（至少 12 位）','Password (at least 12 characters)')}}<input v-model="password" type="password" :autocomplete="mode==='register'?'new-password':'current-password'" minlength="12" maxlength="128" required/></label><label v-if="mode==='register'"><input v-model="accept" type="checkbox" required/>{{label('同意上述社区规则与账号隐私说明','I accept the community rules and account privacy terms')}}</label><button class="button primary" :disabled="busy">{{mode==='register'?label('创建账号','Create account'):label('登录','Sign in')}}</button></form></section>
<section v-else class="world-preferences"><p>{{label('已登录：','Signed in: ')}}{{user.name}} <button class="button" :disabled="busy" @click="logout">{{label('退出','Sign out')}}</button></p><form class="forum-form" @submit.prevent="publish"><h2>{{topic?label('回复讨论','Reply'):label('发表主题','New topic')}}</h2><label v-if="!topic">{{label('标题','Title')}}<input v-model="title" minlength="3" maxlength="120" required/></label><label>{{label('内容（纯文字，最多 5000 字）','Message (plain text, up to 5000 characters)')}}<textarea v-model="body" minlength="3" maxlength="5000" rows="5" required/></label><button class="button primary" :disabled="busy">{{label('提交','Submit')}}</button></form></section>
<section v-if="user?.admin" class="world-preferences"><h2>{{label('管理员审核','Moderation queue')}}</h2><article v-for="post in queue" :key="post.id" class="forum-post"><h3>{{post.title}}</h3><p class="forum-body">{{post.body}}</p><p>{{post.author}} · {{post.status}} · {{label('举报','Reports')}} {{post.reports}}</p><button class="button" :disabled="busy" @click="moderate(post.id,'published')">{{label('通过并公开','Approve')}}</button><button class="button" :disabled="busy" @click="moderate(post.id,'rejected')">{{label('拒绝','Reject')}}</button></article><p v-if="!queue.length">{{label('暂无待审核内容','No pending content')}}</p></section>
<section><div class="section-heading"><h2>{{topic?topic.title:label('围场讨论','Paddock discussions')}}</h2><button v-if="topic" class="button" @click="select(null)">{{label('返回主题','All topics')}}</button><button class="button" :disabled="busy" @click="run(load)">{{label('刷新','Refresh')}}</button></div><article v-if="topic" class="forum-post"><p class="forum-body">{{topic.body}}</p><p>{{topic.author}}</p></article><article v-for="post in posts" :key="post.id" class="forum-post"><button v-if="!topic" class="forum-title" @click="select(post)">{{post.title}}</button><p class="forum-body">{{post.body}}</p><p class="caption">{{post.author}} · {{new Date(post.created).toLocaleString(locale)}} · {{post.status==='published'?label('已公开','Published'):label('待审核或未公开','Awaiting review / hidden')}}</p><button v-if="user" class="button" @click="reportId=post.id">{{label('举报','Report')}}</button><button v-if="post.own||user?.admin" class="button" :disabled="busy" @click="remove(post.id)">{{label('删除','Delete')}}</button></article><p v-if="!posts.length&&!busy" class="empty-inline">{{label('暂无讨论。成为第一个分享观点的车迷。','No discussions yet. Share the first perspective.')}}</p></section>
<form v-if="reportId" class="forum-form world-preferences" @submit.prevent="report"><label>{{label('举报原因','Report reason')}}<textarea v-model="reason" minlength="3" maxlength="500" required/></label><button class="button" :disabled="busy">{{label('提交举报','Send report')}}</button><button type="button" class="button" @click="reportId=0">{{label('取消','Cancel')}}</button></form>
<details v-if="user&&!user.admin" class="world-preferences"><summary>{{label('注销账号','Delete account')}}</summary><p>{{label('账号及发布内容将被删除；请输入用户名确认。','Your account and published content will be deleted. Type your username to confirm.')}}</p><form @submit.prevent="deleteAccount"><input v-model="confirmName" :placeholder="user.name" required/><button class="button" :disabled="busy||confirmName!==user.name">{{label('注销账号并删除内容','Delete account and content')}}</button></form></details>
</template>
